 [Serializable]class Receipt{public bool passed,osInputTest=false,rangedChoice;public string stage,error,buildGuid;public string[] checks;}
 Receipt r=new Receipt();List<string> checks=new List<string>();string output;WarSandboxRuntimeDeployment d;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();if(!a.Contains("--roster31-smoke"))return;var g=new GameObject("Roster31 isolated smoke");DontDestroyOnLoad(g);g.AddComponent<Roster31PlayerSmoke>().output=a.First(x=>x.StartsWith("--terrain-output=")).Substring("--terrain-output=".Length);}
