 IEnumerator Run(){r.stage="load";yield return new WaitForSecondsRealtime(3);var session=WarSandboxSceneSession.Instance;B("home-play").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);int season=Environment.GetCommandLineArgs().Contains("--winter")?2:0;B("card-"+season).onClick.Invoke();yield return new WaitForSecondsRealtime(.2f);B("card-"+season+"-enter").onClick.Invoke();float end=Time.realtimeSinceStartup+120;while(session.IsLoading&&Time.realtimeSinceStartup<end)yield return null;yield return new WaitForSecondsRealtime(.7f);Check(session.State==WarSandboxEntryState.Battle&&!session.HelpOpen,"Load/isolated intro suppression failed");d=session.Controller.GetComponent<WarSandboxRuntimeDeployment>();Check(RosterInfo31.Active(d)&&d.IsEditing,"Not Roster31 draft");d.PlanStore=new WarSandboxLocalPlanStore(Path.Combine(output,"isolated-plans"));var original=d.Draft[0].template;var other=d.Draft[1];string initial=PlanState28.For(session.Controller).Current;Check(T("army-name-0").text.Contains("当前")&&T("army-composition31-0").text==RosterInfo31.Composition(d.Draft,0),"Overview composition/selection wrong");Fit("army-composition31-0");Shot("01-overview");yield return new WaitForSecondsRealtime(.3f);
