  B("field-unit-stats").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(Field("st-r-attackDamage-field").text=="57","Detailed value disagrees");Field("st-r-attackDamage-field").onEndEdit.Invoke("69");yield return new WaitForSecondsRealtime(.3f);Check(Field("st-r-attackDamage-field").text=="69"&&T("st-r-attackDamage-src-text").text.Contains("本局"),"Detail local edit failed");B("st-done").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Dossier(original);Check(T("legion-stat-source31-1").text.Contains("本局")&&T("legion-stat-value-1").text=="69","Local source not synchronized");Shot("03-local-source");yield return new WaitForSecondsRealtime(.3f);
  d.Draft.SetStat(original,WarSandboxUnitStat.AttackDamage,official);yield return new WaitForSecondsRealtime(.25f);Check(T("legion-stat-source31-1").text.Contains("本局"),"Equal-to-official override lost its true source");d.Draft.ClearStat(original,WarSandboxUnitStat.AttackDamage);yield return new WaitForSecondsRealtime(.25f);Check(T("legion-stat-value-1").text=="57"&&T("legion-stat-source31-1").text.Contains("全局"),"Clearing local did not reveal global");Check(d.Draft.SetStat(original,WarSandboxUnitStat.AttackDamage,69),"Restore local failed");yield return new WaitForSecondsRealtime(.3f);checks.Add("Official/global/local values match resolver and detailed page; equal-value local remains labeled local; clearing reveals global");
  r.stage="picker";int current=d.ChoiceTemplates.ToList().IndexOf(original);B("field-template").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);string before=PlanState28.For(session.Controller).Current;Check(T("picker-title").text.Contains("攻方")&&T("picker-title").text.Contains("01"),"Picker does not identify edited army/formation");Check(T("picker-source31-"+current).text==RosterInfo31.Sources(d,original)&&T("picker-stats-"+current).text.Contains("69"),"Picker local value/source stale");Fit("picker-source31-"+current);Fit("picker-extra31-"+current);Shot("04-picker-values");yield return new WaitForSecondsRealtime(.3f);B("picker-filter-2").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(PlanState28.For(session.Controller).Current==before,"Filter changes draft");B("picker-back").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(d.Draft[0].template==original&&PlanState28.For(session.Controller).Current==before,"Cancel picker changes composition");
  int alternate=Enumerable.Range(0,d.ChoiceTemplates.Count).FirstOrDefault(i=>WarSandboxUnitStats.IsRanged(d.ChoiceTemplates[i])&&d.ChoiceTemplates[i]!=original);if(d.ChoiceTemplates[alternate]==original)alternate=Enumerable.Range(0,d.ChoiceTemplates.Count).First(i=>d.ChoiceTemplates[i]!=original);var replacement=d.ChoiceTemplates[alternate];r.rangedChoice=WarSandboxUnitStats.IsRanged(replacement);var expected=d.rosterPolicy!=null?d.rosterPolicy.Select(d.Draft[0],replacement):d.Draft[0];expected.template=replacement;
  B("field-template").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);B("template-"+alternate).onClick.Invoke();yield return new WaitForSecondsRealtime(.4f);Check(d.Draft[0].template==replacement&&d.Draft[0].count==expected.count&&d.Draft[0].center==expected.center&&d.Draft[0].teamId==0,"Selection changed existing policy semantics");Check(T("legion-unit-name").text==d.Draft[0].Name&&T("formation-name-0").text==d.Draft[0].Name,"Names not synchronized");Dossier(replacement);Check(d.Draft[1].template==other.template&&d.Draft[1].count==other.count,"Changed other army");checks.Add("Picker identifies scope, filters/cancel do not mutate; replacement follows existing policy, preserves other army and synchronizes names/values");
  r.stage="counts-and-undo";int prior=d.Draft[0].count;Field("input-count").text="900";Check(d.Draft[0].count==prior,"Raw input prematurely committed");B("legion-update-count").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(d.Draft[0].count==900&&T("formation-count-0").text.Contains("900")&&T("legion-total").text.Contains("900"),"Count not synchronized");B("legion-done").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(T("army-summary-0").text.Contains("900")&&T("army-composition31-0").text==RosterInfo31.Composition(d.Draft,0),"Overview stale after count edit");Shot("05-updated-overview");yield return new WaitForSecondsRealtime(.3f);Check(d.Draft.Undo(),"Undo missing");yield return new WaitForSecondsRealtime(.3f);Check(d.Draft[0].count==prior&&T("army-composition31-0").text==RosterInfo31.Composition(d.Draft,0),"Undo did not update overview");Check(d.Draft.Redo(),"Redo missing");yield return new WaitForSecondsRealtime(.3f);Check(d.Draft[0].count==900,"Redo mismatch");B("army-details-1").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(T("legion-name").text.Contains("守方")&&T("formation-role-1").text.Contains("正在编辑"),"Selected army/formation wrong");Dossier(other.template);B("legion-done").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(T("army-name-1").text.Contains("当前")&&!T("army-name-0").text.Contains("当前"),"Selected marker stale");checks.Add("Count edit/Undo/Redo updates summaries; selection follows the correct army and formation");
  r.stage="persistence";Check(d.TrySavePlan("QA31","Isolated roster check",false,out error),error);string saved=PlanState28.For(session.Controller).Current;var changed=d.Draft[0];changed.count=800;d.Draft.Set(0,changed);Check(d.TryLoadPlan("QA31",out error),error);yield return new WaitForSecondsRealtime(.3f);Check(PlanState28.For(session.Controller).Current==saved&&T("army-summary-0").text.Contains("900"),"Reload stale or lost data");Check(WarSandboxUnitStats.TryGetOfficial(original,def,out var unchanged)&&unchanged==official,"Official asset modified");checks.Add("Real saved plan reload keeps names/counts/templates/stats; official template value unchanged");r.stage="complete";
